CREATE TABLE dbo.EmrRecords (
  EmrRecordId UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_EmrRecords_Id DEFAULT NEWSEQUENTIALID(), VisitId UNIQUEIDENTIFIER NOT NULL,
  PatientId UNIQUEIDENTIFIER NOT NULL, DoctorId UNIQUEIDENTIFIER NOT NULL, Status VARCHAR(20) NOT NULL CONSTRAINT DF_EmrRecords_Status DEFAULT 'DRAFT',
  CurrentVersionNo INT NOT NULL CONSTRAINT DF_EmrRecords_VersionNo DEFAULT 1, SignedAt DATETIME2 NULL,
  CreatedAt DATETIME2 NOT NULL CONSTRAINT DF_EmrRecords_CreatedAt DEFAULT SYSUTCDATETIME(), CreatedBy VARCHAR(100) NOT NULL, OriginalId UNIQUEIDENTIFIER NULL, Version ROWVERSION NOT NULL,
  CONSTRAINT PK_EmrRecords PRIMARY KEY(EmrRecordId), CONSTRAINT UQ_EmrRecords_Visit UNIQUE(VisitId),
  CONSTRAINT FK_EmrRecords_Visit FOREIGN KEY(VisitId) REFERENCES dbo.Visits(VisitId), CONSTRAINT FK_EmrRecords_Patient FOREIGN KEY(PatientId) REFERENCES dbo.Patients(PatientId),
  CONSTRAINT FK_EmrRecords_Doctor FOREIGN KEY(DoctorId) REFERENCES dbo.Users(UserId), CONSTRAINT FK_EmrRecords_Original FOREIGN KEY(OriginalId) REFERENCES dbo.EmrRecords(EmrRecordId),
  CONSTRAINT CK_EmrRecords_Status CHECK(Status IN ('DRAFT','PENDING_SIGNATURE','SIGNED','VOID'))
);
CREATE TABLE dbo.EmrVersions (
  EmrVersionId UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_EmrVersions_Id DEFAULT NEWSEQUENTIALID(), EmrRecordId UNIQUEIDENTIFIER NOT NULL,
  VersionNo INT NOT NULL, ClinicalContentJson NVARCHAR(MAX) NOT NULL, AuthoredBy UNIQUEIDENTIFIER NOT NULL,
  Status VARCHAR(20) NOT NULL CONSTRAINT DF_EmrVersions_Status DEFAULT 'DRAFT', SignedAt DATETIME2 NULL, SignatureHash CHAR(64) NULL,
  CreatedAt DATETIME2 NOT NULL CONSTRAINT DF_EmrVersions_CreatedAt DEFAULT SYSUTCDATETIME(), OriginalId UNIQUEIDENTIFIER NULL,
  CONSTRAINT PK_EmrVersions PRIMARY KEY(EmrVersionId), CONSTRAINT UQ_EmrVersions_Record_Version UNIQUE(EmrRecordId, VersionNo),
  CONSTRAINT FK_EmrVersions_Record FOREIGN KEY(EmrRecordId) REFERENCES dbo.EmrRecords(EmrRecordId), CONSTRAINT FK_EmrVersions_Author FOREIGN KEY(AuthoredBy) REFERENCES dbo.Users(UserId),
  CONSTRAINT FK_EmrVersions_Original FOREIGN KEY(OriginalId) REFERENCES dbo.EmrVersions(EmrVersionId), CONSTRAINT CK_EmrVersions_Json CHECK(ISJSON(ClinicalContentJson)=1),
  CONSTRAINT CK_EmrVersions_Status CHECK(Status IN ('DRAFT','SIGNED','SUPERSEDED','VOID'))
);
CREATE TABLE dbo.Diagnoses (
  DiagnosisId UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_Diagnoses_Id DEFAULT NEWSEQUENTIALID(), EmrVersionId UNIQUEIDENTIFIER NOT NULL,
  Code VARCHAR(30) NULL, Description NVARCHAR(500) NOT NULL, IsPrimary BIT NOT NULL CONSTRAINT DF_Diagnoses_Primary DEFAULT 0,
  CreatedAt DATETIME2 NOT NULL CONSTRAINT DF_Diagnoses_CreatedAt DEFAULT SYSUTCDATETIME(), CreatedBy VARCHAR(100) NOT NULL,
  CONSTRAINT PK_Diagnoses PRIMARY KEY(DiagnosisId), CONSTRAINT FK_Diagnoses_EmrVersion FOREIGN KEY(EmrVersionId) REFERENCES dbo.EmrVersions(EmrVersionId)
);
CREATE TABLE dbo.ToothChart (
  ToothChartId UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_ToothChart_Id DEFAULT NEWSEQUENTIALID(), EmrVersionId UNIQUEIDENTIFIER NOT NULL,
  ToothCode VARCHAR(20) NOT NULL, SurfaceCode VARCHAR(20) NULL, FindingCode VARCHAR(50) NOT NULL, Note NVARCHAR(500) NULL,
  CreatedAt DATETIME2 NOT NULL CONSTRAINT DF_ToothChart_CreatedAt DEFAULT SYSUTCDATETIME(), CreatedBy VARCHAR(100) NOT NULL,
  CONSTRAINT PK_ToothChart PRIMARY KEY(ToothChartId), CONSTRAINT FK_ToothChart_EmrVersion FOREIGN KEY(EmrVersionId) REFERENCES dbo.EmrVersions(EmrVersionId)
);
CREATE TABLE dbo.TreatmentPlans (
  TreatmentPlanId UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_TreatmentPlans_Id DEFAULT NEWSEQUENTIALID(), VisitId UNIQUEIDENTIFIER NOT NULL,
  PatientId UNIQUEIDENTIFIER NOT NULL, DoctorId UNIQUEIDENTIFIER NOT NULL, PhaseNo INT NOT NULL, Status VARCHAR(20) NOT NULL CONSTRAINT DF_TreatmentPlans_Status DEFAULT 'DRAFT',
  PlanJson NVARCHAR(MAX) NOT NULL, AcceptedAt DATETIME2 NULL, CreatedAt DATETIME2 NOT NULL CONSTRAINT DF_TreatmentPlans_CreatedAt DEFAULT SYSUTCDATETIME(), CreatedBy VARCHAR(100) NOT NULL, Version ROWVERSION NOT NULL,
  CONSTRAINT PK_TreatmentPlans PRIMARY KEY(TreatmentPlanId), CONSTRAINT FK_TreatmentPlans_Visit FOREIGN KEY(VisitId) REFERENCES dbo.Visits(VisitId),
  CONSTRAINT FK_TreatmentPlans_Patient FOREIGN KEY(PatientId) REFERENCES dbo.Patients(PatientId), CONSTRAINT FK_TreatmentPlans_Doctor FOREIGN KEY(DoctorId) REFERENCES dbo.Users(UserId),
  CONSTRAINT CK_TreatmentPlans_Phase CHECK(PhaseNo > 0), CONSTRAINT CK_TreatmentPlans_Json CHECK(ISJSON(PlanJson)=1),
  CONSTRAINT CK_TreatmentPlans_Status CHECK(Status IN ('DRAFT','PROPOSED','ACCEPTED','IN_PROGRESS','COMPLETED','CANCELLED'))
);
CREATE TABLE dbo.Prescriptions (
  PrescriptionId UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_Prescriptions_Id DEFAULT NEWSEQUENTIALID(), VisitId UNIQUEIDENTIFIER NOT NULL,
  DoctorId UNIQUEIDENTIFIER NOT NULL, Status VARCHAR(20) NOT NULL CONSTRAINT DF_Prescriptions_Status DEFAULT 'DRAFT', PrescriptionJson NVARCHAR(MAX) NOT NULL,
  SignedAt DATETIME2 NULL, CreatedAt DATETIME2 NOT NULL CONSTRAINT DF_Prescriptions_CreatedAt DEFAULT SYSUTCDATETIME(), CreatedBy VARCHAR(100) NOT NULL,
  CONSTRAINT PK_Prescriptions PRIMARY KEY(PrescriptionId), CONSTRAINT FK_Prescriptions_Visit FOREIGN KEY(VisitId) REFERENCES dbo.Visits(VisitId),
  CONSTRAINT FK_Prescriptions_Doctor FOREIGN KEY(DoctorId) REFERENCES dbo.Users(UserId), CONSTRAINT CK_Prescriptions_Json CHECK(ISJSON(PrescriptionJson)=1),
  CONSTRAINT CK_Prescriptions_Status CHECK(Status IN ('DRAFT','SIGNED','CANCELLED'))
);
CREATE TABLE dbo.ClinicalOrders (
  ClinicalOrderId UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_ClinicalOrders_Id DEFAULT NEWSEQUENTIALID(), VisitId UNIQUEIDENTIFIER NOT NULL,
  DoctorId UNIQUEIDENTIFIER NOT NULL, OrderType VARCHAR(30) NOT NULL, OrderJson NVARCHAR(MAX) NOT NULL,
  Status VARCHAR(20) NOT NULL CONSTRAINT DF_ClinicalOrders_Status DEFAULT 'ORDERED', CreatedAt DATETIME2 NOT NULL CONSTRAINT DF_ClinicalOrders_CreatedAt DEFAULT SYSUTCDATETIME(), CreatedBy VARCHAR(100) NOT NULL,
  CONSTRAINT PK_ClinicalOrders PRIMARY KEY(ClinicalOrderId), CONSTRAINT FK_ClinicalOrders_Visit FOREIGN KEY(VisitId) REFERENCES dbo.Visits(VisitId),
  CONSTRAINT FK_ClinicalOrders_Doctor FOREIGN KEY(DoctorId) REFERENCES dbo.Users(UserId), CONSTRAINT CK_ClinicalOrders_Json CHECK(ISJSON(OrderJson)=1),
  CONSTRAINT CK_ClinicalOrders_Status CHECK(Status IN ('ORDERED','IN_PROGRESS','COMPLETED','CANCELLED'))
);
CREATE TABLE dbo.Consents (
  ConsentId UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_Consents_Id DEFAULT NEWSEQUENTIALID(), VisitId UNIQUEIDENTIFIER NOT NULL,
  ConsentTemplateId UNIQUEIDENTIFIER NOT NULL, PatientId UNIQUEIDENTIFIER NOT NULL, SignerName NVARCHAR(200) NULL,
  SignerRelationship NVARCHAR(100) NULL, Status VARCHAR(20) NOT NULL CONSTRAINT DF_Consents_Status DEFAULT 'DRAFT', PresentedAt DATETIME2 NULL,
  SignedAt DATETIME2 NULL, RevokedAt DATETIME2 NULL, SignatureData VARBINARY(MAX) NULL, RevocationReason NVARCHAR(500) NULL,
  CreatedAt DATETIME2 NOT NULL CONSTRAINT DF_Consents_CreatedAt DEFAULT SYSUTCDATETIME(), CreatedBy VARCHAR(100) NOT NULL, OriginalId UNIQUEIDENTIFIER NULL,
  CONSTRAINT PK_Consents PRIMARY KEY(ConsentId), CONSTRAINT FK_Consents_Visit FOREIGN KEY(VisitId) REFERENCES dbo.Visits(VisitId),
  CONSTRAINT FK_Consents_Template FOREIGN KEY(ConsentTemplateId) REFERENCES dbo.ConsentTemplates(ConsentTemplateId), CONSTRAINT FK_Consents_Patient FOREIGN KEY(PatientId) REFERENCES dbo.Patients(PatientId),
  CONSTRAINT FK_Consents_Original FOREIGN KEY(OriginalId) REFERENCES dbo.Consents(ConsentId), CONSTRAINT CK_Consents_Status CHECK(Status IN ('DRAFT','PRESENTED','SIGNED','REVOKED','VOID'))
);
CREATE TABLE dbo.EmrAddenda (
  EmrAddendumId UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_EmrAddenda_Id DEFAULT NEWSEQUENTIALID(), EmrVersionId UNIQUEIDENTIFIER NOT NULL,
  Content NVARCHAR(MAX) NOT NULL, Reason NVARCHAR(500) NOT NULL, AuthoredBy UNIQUEIDENTIFIER NOT NULL, SignedAt DATETIME2 NOT NULL,
  CreatedAt DATETIME2 NOT NULL CONSTRAINT DF_EmrAddenda_CreatedAt DEFAULT SYSUTCDATETIME(),
  CONSTRAINT PK_EmrAddenda PRIMARY KEY(EmrAddendumId), CONSTRAINT FK_EmrAddenda_Version FOREIGN KEY(EmrVersionId) REFERENCES dbo.EmrVersions(EmrVersionId),
  CONSTRAINT FK_EmrAddenda_Author FOREIGN KEY(AuthoredBy) REFERENCES dbo.Users(UserId)
);
CREATE TABLE dbo.ServiceLines (
  ServiceLineId UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_ServiceLines_Id DEFAULT NEWSEQUENTIALID(), VisitId UNIQUEIDENTIFIER NOT NULL,
  TreatmentPlanId UNIQUEIDENTIFIER NULL, ServiceId UNIQUEIDENTIFIER NOT NULL, PriceVersionId UNIQUEIDENTIFIER NOT NULL, Quantity DECIMAL(18,4) NOT NULL,
  ApprovedUnitPrice DECIMAL(18,2) NOT NULL, Status VARCHAR(20) NOT NULL CONSTRAINT DF_ServiceLines_Status DEFAULT 'PLANNED',
  ToothCode VARCHAR(20) NULL, CreatedAt DATETIME2 NOT NULL CONSTRAINT DF_ServiceLines_CreatedAt DEFAULT SYSUTCDATETIME(), CreatedBy VARCHAR(100) NOT NULL, Version ROWVERSION NOT NULL,
  CONSTRAINT PK_ServiceLines PRIMARY KEY(ServiceLineId), CONSTRAINT FK_ServiceLines_Visit FOREIGN KEY(VisitId) REFERENCES dbo.Visits(VisitId),
  CONSTRAINT FK_ServiceLines_Plan FOREIGN KEY(TreatmentPlanId) REFERENCES dbo.TreatmentPlans(TreatmentPlanId), CONSTRAINT FK_ServiceLines_Service FOREIGN KEY(ServiceId) REFERENCES dbo.Services(ServiceId),
  CONSTRAINT FK_ServiceLines_Price FOREIGN KEY(PriceVersionId) REFERENCES dbo.ServicePriceVersions(PriceVersionId),
  CONSTRAINT CK_ServiceLines_Quantity CHECK(Quantity > 0), CONSTRAINT CK_ServiceLines_Price CHECK(ApprovedUnitPrice >= 0),
  CONSTRAINT CK_ServiceLines_Status CHECK(Status IN ('PLANNED','IN_PROGRESS','COMPLETED','CANCELLED','REVERSED'))
);
CREATE TABLE dbo.ServiceCompletionEvents (
  ServiceCompletionEventId UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_ServiceCompletion_Id DEFAULT NEWSEQUENTIALID(), ServiceLineId UNIQUEIDENTIFIER NOT NULL,
  CompletionVersion INT NOT NULL, QuantityCompleted DECIMAL(18,4) NOT NULL, CompletedBy UNIQUEIDENTIFIER NOT NULL, CompletedAt DATETIME2 NOT NULL,
  Result NVARCHAR(1000) NULL, EventType VARCHAR(20) NOT NULL CONSTRAINT DF_ServiceCompletion_Type DEFAULT 'COMPLETION', OriginalId UNIQUEIDENTIFIER NULL,
  CreatedAt DATETIME2 NOT NULL CONSTRAINT DF_ServiceCompletion_CreatedAt DEFAULT SYSUTCDATETIME(), CreatedBy VARCHAR(100) NOT NULL,
  CONSTRAINT PK_ServiceCompletionEvents PRIMARY KEY(ServiceCompletionEventId), CONSTRAINT UQ_ServiceCompletion_Line_Version UNIQUE(ServiceLineId, CompletionVersion),
  CONSTRAINT FK_ServiceCompletion_Line FOREIGN KEY(ServiceLineId) REFERENCES dbo.ServiceLines(ServiceLineId), CONSTRAINT FK_ServiceCompletion_User FOREIGN KEY(CompletedBy) REFERENCES dbo.Users(UserId),
  CONSTRAINT FK_ServiceCompletion_Original FOREIGN KEY(OriginalId) REFERENCES dbo.ServiceCompletionEvents(ServiceCompletionEventId),
  CONSTRAINT CK_ServiceCompletion_Quantity CHECK(QuantityCompleted > 0), CONSTRAINT CK_ServiceCompletion_Type CHECK(EventType IN ('COMPLETION','ADJUSTMENT','REVERSAL'))
);
CREATE TABLE dbo.SignQueue (
  SignQueueId UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_SignQueue_Id DEFAULT NEWSEQUENTIALID(), EmrRecordId UNIQUEIDENTIFIER NOT NULL,
  RequestedBy UNIQUEIDENTIFIER NOT NULL, RequestedAt DATETIME2 NOT NULL CONSTRAINT DF_SignQueue_RequestedAt DEFAULT SYSUTCDATETIME(), DueAt DATETIME2 NOT NULL,
  Status VARCHAR(20) NOT NULL CONSTRAINT DF_SignQueue_Status DEFAULT 'PENDING', FailureReason NVARCHAR(500) NULL, Version ROWVERSION NOT NULL,
  CONSTRAINT PK_SignQueue PRIMARY KEY(SignQueueId), CONSTRAINT FK_SignQueue_Record FOREIGN KEY(EmrRecordId) REFERENCES dbo.EmrRecords(EmrRecordId),
  CONSTRAINT FK_SignQueue_User FOREIGN KEY(RequestedBy) REFERENCES dbo.Users(UserId), CONSTRAINT CK_SignQueue_Due CHECK(DueAt > RequestedAt),
  CONSTRAINT CK_SignQueue_Status CHECK(Status IN ('PENDING','SIGNED','FAILED','EXPIRED','CANCELLED'))
);
